class_name VoxelMesh
extends RefCounted
## Builds flat-shaded voxel meshes with per-voxel vertex colours.
## Faces hidden between neighbouring voxels are culled, so a whole yard of
## blocks costs only a few thousand triangles.

const DIRS: Array[Vector3i] = [
	Vector3i(1, 0, 0), Vector3i(-1, 0, 0),
	Vector3i(0, 1, 0), Vector3i(0, -1, 0),
	Vector3i(0, 0, 1), Vector3i(0, 0, -1),
]

static var _material: StandardMaterial3D


## Shared material that takes albedo from vertex colours.
static func material() -> StandardMaterial3D:
	if _material == null:
		_material = StandardMaterial3D.new()
		_material.vertex_color_use_as_albedo = true
		_material.roughness = 0.95
		_material.specular = 0.15
	return _material


## color_at(x, y, z) returns a Color for a solid voxel, or null for empty space.
## The mesh is centred on the origin, then shifted by `offset`.
static func build(size: Vector3i, voxel: float, color_at: Callable,
		jitter := 0.12, offset := Vector3.ZERO) -> ArrayMesh:
	var filled := {}
	for x in size.x:
		for y in size.y:
			for z in size.z:
				var c = color_at.call(x, y, z)
				if c != null:
					filled[Vector3i(x, y, z)] = c

	var verts := PackedVector3Array()
	var norms := PackedVector3Array()
	var cols := PackedColorArray()
	var half := Vector3(size) * 0.5
	var h := voxel * 0.5
	for p: Vector3i in filled:
		var base: Color = filled[p]
		var j := 1.0 - jitter * 0.5 + jitter * float(absi(hash(p)) % 1000) / 1000.0
		var col := Color(base.r * j, base.g * j, base.b * j, 1.0)
		var center := (Vector3(p) + Vector3(0.5, 0.5, 0.5) - half) * voxel + offset
		for d in DIRS:
			if filled.has(p + d):
				continue
			var n := Vector3(d)
			var u := Vector3(n.y, n.z, n.x)
			var v := n.cross(u)
			var c := center + n * h
			var a := c - u * h - v * h
			var b := c + u * h - v * h
			var cc := c + u * h + v * h
			var dd := c - u * h + v * h
			# Godot treats clockwise triangles as front-facing.
			for q in [a, cc, b, a, dd, cc]:
				verts.append(q)
				norms.append(n)
				cols.append(col)

	var arrays := []
	arrays.resize(Mesh.ARRAY_MAX)
	arrays[Mesh.ARRAY_VERTEX] = verts
	arrays[Mesh.ARRAY_NORMAL] = norms
	arrays[Mesh.ARRAY_COLOR] = cols
	var mesh := ArrayMesh.new()
	if verts.is_empty():
		return mesh
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
	mesh.surface_set_material(0, material())
	return mesh


## Deterministic 0..1 noise per voxel, handy inside colour callbacks.
static func rand3(x: int, y: int, z: int, salt := 0) -> float:
	return float(absi(hash(Vector3i(x * 73 + salt, y * 19 - salt, z * 31 + salt * 7))) % 1000) / 1000.0


## Smooth 0..1 value noise over a 2D grid, used to blot grass onto the ground.
static func noise2(x: float, z: float, salt := 0) -> float:
	var xi := int(floor(x))
	var zi := int(floor(z))
	var xf := x - xi
	var zf := z - zi
	# Smoothstep the interpolants so blotches have soft, organic edges.
	xf = xf * xf * (3.0 - 2.0 * xf)
	zf = zf * zf * (3.0 - 2.0 * zf)
	var v00 := rand3(xi, 0, zi, salt)
	var v10 := rand3(xi + 1, 0, zi, salt)
	var v01 := rand3(xi, 0, zi + 1, salt)
	var v11 := rand3(xi + 1, 0, zi + 1, salt)
	return lerpf(lerpf(v00, v10, xf), lerpf(v01, v11, xf), zf)

class_name Palette
extends RefCounted
## The grim, dirty, blood-flecked colour set pulled from the old Zombox caps:
## everything is desaturated and dark, with red used only where it hurts.

# Ground
const DIRT_DARK := Color(0.17, 0.13, 0.09)
const DIRT := Color(0.27, 0.21, 0.14)
const DIRT_WET := Color(0.13, 0.11, 0.08)
const GRASS_DARK := Color(0.13, 0.20, 0.08)
const GRASS := Color(0.20, 0.31, 0.12)
const GRASS_LIGHT := Color(0.31, 0.42, 0.16)

# Masonry
const STONE := Color(0.20, 0.19, 0.18)
const STONE_DARK := Color(0.12, 0.115, 0.11)
const STONE_LIGHT := Color(0.28, 0.27, 0.25)
const BRICK := Color(0.26, 0.13, 0.10)
const BRICK_DARK := Color(0.16, 0.08, 0.06)

# Flies and filth
const BLOOD := Color(0.30, 0.03, 0.03)
const BLOOD_DARK := Color(0.17, 0.02, 0.02)
const BONE := Color(0.52, 0.49, 0.41)

# The blockhead
const SKIN := Color(0.84, 0.68, 0.42)
const SKIN_SHADE := Color(0.70, 0.55, 0.32)
const SHIRT := Color(0.86, 0.71, 0.44)
const PANTS := Color(0.72, 0.57, 0.33)
const SHOE := Color(0.30, 0.22, 0.12)
const STRAP := Color(0.45, 0.30, 0.16)
const EYE := Color(0.10, 0.07, 0.04)
const PACK := Color(0.34, 0.26, 0.15)

# Props
const WOOD := Color(0.42, 0.28, 0.14)
const WOOD_LIGHT := Color(0.55, 0.38, 0.19)
const WOOD_DARK := Color(0.24, 0.15, 0.07)
const BARREL_RED := Color(0.55, 0.11, 0.07)
const BARREL_BAND := Color(0.16, 0.15, 0.14)
const RUST := Color(0.45, 0.28, 0.10)
const IRON := Color(0.30, 0.30, 0.33)
const MEAT := Color(0.72, 0.12, 0.10)
const MEAT_DARK := Color(0.45, 0.07, 0.06)


## Slightly varies a colour so nothing looks flat and hand-placed.
static func vary(c: Color, seed: int, amount := 0.1) -> Color:
	var j := 1.0 - amount + 2.0 * amount * VoxelMesh.rand3(seed, 0, 0)
	return Color(clampf(c.r * j, 0, 1), clampf(c.g * j, 0, 1), clampf(c.b * j, 0, 1))

class_name VoxelRig
extends Node3D
## The blockhead: eleven voxel parts on pivot nodes that are posed by code while
## upright, and that can flip into a real jointed physics ragdoll at any instant.
## Getting up blends every part from where it lies back into the walk pose.
##
## Parts, and the joints that hold the ragdoll together:
##
##        head  --neck--  torso  --shoulder--  arm_l / arm_r
##          |                |
##        pack           pelvis
##                          |--hip-- leg_l --ankle-- foot_l
##                          |        leg_r --ankle-- foot_r
##
## The tool is not jointed: it is held by collision exceptions, so it flies
## loose the moment you go down and clatters away across the yard.

const VS := 0.1
const RECOVER_TIME := 0.5

## key -> { pivot, mesh, rest, mass }
var parts := {}
var is_ragdoll := false
var recovering := false

var pelvis: Node3D
var torso: Node3D
var head: Node3D
var pack: Node3D
var arm_l: Node3D
var arm_r: Node3D
var leg_l: Node3D
var leg_r: Node3D
var foot_l: Node3D
var foot_r: Node3D

var _joints: Array[Joint3D] = []
var _rest_pos := {}
var _recover_t := 0.0
var _recover_from := {}


func build() -> void:
	pelvis = _pivot(self, Vector3(0, 0.72, 0))
	torso = _pivot(self, Vector3(0, 0.82, 0))
	head = _pivot(torso, Vector3(0, 0.60, 0))
	pack = _pivot(torso, Vector3(0, 0.30, -0.26))
	arm_l = _pivot(torso, Vector3(-0.40, 0.55, 0))
	arm_r = _pivot(torso, Vector3(0.40, 0.55, 0))
	leg_l = _pivot(self, Vector3(-0.12, 0.66, 0))
	leg_r = _pivot(self, Vector3(0.12, 0.66, 0))
	foot_l = _pivot(leg_l, Vector3(0, -0.50, 0))
	foot_r = _pivot(leg_r, Vector3(0, -0.50, 0))

	_part("pelvis", pelvis, Vector3.ZERO, 2.0,
		_vox(Vector3i(5, 2, 4), func(x, y, z): return Palette.PANTS if y == 0 else Palette.SKIN_SHADE))
	_part("torso", torso, Vector3(0, 0.30, 0), 3.2,
		_vox(Vector3i(6, 6, 4), _torso_col))
	_part("head", head, Vector3(0, 0.25, 0), 1.1,
		_vox(Vector3i(5, 5, 5), _head_col))
	_part("pack", pack, Vector3.ZERO, 0.5,
		_vox(Vector3i(4, 4, 2), func(x, y, z): return Palette.PACK if z == 0 else Palette.PACK.darkened(0.25)))
	_part("arm_l", arm_l, Vector3(0, -0.25, 0), 0.7,
		_vox(Vector3i(2, 6, 2), _arm_col))
	_part("arm_r", arm_r, Vector3(0, -0.25, 0), 0.7,
		_vox(Vector3i(2, 6, 2), _arm_col))
	_part("leg_l", leg_l, Vector3(0, -0.25, 0), 1.0,
		_vox(Vector3i(2, 5, 2), _leg_col))
	_part("leg_r", leg_r, Vector3(0, -0.25, 0), 1.0,
		_vox(Vector3i(2, 5, 2), _leg_col))
	_part("foot_l", foot_l, Vector3(0, 0, 0.03), 0.4,
		_vox(Vector3i(2, 1, 3), func(x, y, z): return Palette.SHOE))
	_part("foot_r", foot_r, Vector3(0, 0, 0.03), 0.4,
		_vox(Vector3i(2, 1, 3), func(x, y, z): return Palette.SHOE))

	# A grubby cleaver in the right hand, matching the sword slot in the cap.
	var tool := MeshInstance3D.new()
	tool.mesh = make_cleaver()
	tool.position = Vector3(0, -0.48, 0.06)
	tool.rotation_degrees = Vector3(0, 0, 12)
	arm_r.add_child(tool)
	parts["tool"] = {pivot = arm_r, mesh = tool, rest = tool.transform, mass = 0.6, rb = null}


static func make_cleaver() -> ArrayMesh:
	var steel := Color(0.45, 0.46, 0.50)
	var steel_dark := Color(0.28, 0.29, 0.33)
	var grip := Color(0.30, 0.19, 0.10)
	var f := func(x: int, y: int, z: int) -> Variant:
		if z <= 6:                      # handle
			return grip
		if y >= 5:                      # wide chopping blade
			return steel
		if x == 0 or x == 1:
			return steel_dark
		return null
	return VoxelMesh.build(Vector3i(3, 6, 12), 0.045, f)


func reset_pose() -> void:
	for piv: Node3D in _rest_pos:
		piv.position = _rest_pos[piv]
		piv.rotation = Vector3.ZERO


# --- Ragdoll -----------------------------------------------------------------

## Detaches every part into its own rigid body, wired together with cone-twist
## joints, and throws the whole thing at `vel`.
func go_ragdoll(vel: Vector3, spin := Vector3.ZERO) -> void:
	if is_ragdoll:
		add_velocity(vel)
		return
	if recovering:
		_finish_recover()
	is_ragdoll = true

	var container := get_tree().current_scene
	var bodies: Array[RigidBody3D] = []
	for key in parts:
		var p: Dictionary = parts[key]
		var mi: MeshInstance3D = p.mesh
		var rb := RigidBody3D.new()
		rb.collision_layer = Game.L_RAGDOLL
		rb.collision_mask = Game.L_WORLD | Game.L_CHAR | Game.L_PROP | Game.L_RAGDOLL | Game.L_DEBRIS
		rb.mass = p.mass
		rb.angular_damp = 1.2
		rb.linear_damp = 0.08
		rb.continuous_cd = true
		var aabb: AABB = mi.mesh.get_aabb()
		var box := BoxShape3D.new()
		box.size = aabb.size * 0.9
		var cs := CollisionShape3D.new()
		cs.shape = box
		cs.position = aabb.get_center()
		rb.add_child(cs)
		container.add_child(rb)
		rb.global_transform = mi.global_transform
		mi.reparent(rb)
		rb.linear_velocity = vel
		p.rb = rb
		bodies.append(rb)
	(parts.torso.rb as RigidBody3D).angular_velocity = spin

	_joint("pelvis", "torso", pelvis.global_position, Vector3.UP, 28.0, 22.0)
	_joint("torso", "head", head.global_position, Vector3.UP, 40.0, 30.0)
	_joint("torso", "pack", pack.global_position, -torso.global_basis.z, 20.0, 10.0)
	_joint("torso", "arm_l", arm_l.global_position, -arm_l.global_basis.y, 90.0, 45.0)
	_joint("torso", "arm_r", arm_r.global_position, -arm_r.global_basis.y, 90.0, 45.0)
	_joint("pelvis", "leg_l", leg_l.global_position, -leg_l.global_basis.y, 60.0, 18.0)
	_joint("pelvis", "leg_r", leg_r.global_position, -leg_r.global_basis.y, 60.0, 18.0)
	_joint("leg_l", "foot_l", foot_l.global_position, -leg_l.global_basis.y, 25.0, 6.0)
	_joint("leg_r", "foot_r", foot_r.global_position, -leg_r.global_basis.y, 25.0, 6.0)

	# The cleaver has no joint, so nothing can lever it out of the hand.
	var t: RigidBody3D = parts.tool.rb
	for b in bodies:
		if b != t:
			t.add_collision_exception_with(b)


## Kicks every loose part again — used for a dive into an existing ragdoll.
func add_velocity(v: Vector3) -> void:
	for p: Dictionary in parts.values():
		if p.rb:
			(p.rb as RigidBody3D).linear_velocity += v


func add_angular(v: Vector3) -> void:
	for p: Dictionary in parts.values():
		if p.rb:
			(p.rb as RigidBody3D).angular_velocity += v


## Where the camera, and anything else looking for this character, should point.
func get_focus() -> Vector3:
	if is_ragdoll:
		return (parts.torso.rb as RigidBody3D).global_position
	return torso.global_position + Vector3(0, 0.35, 0)


func torso_velocity() -> Vector3:
	if is_ragdoll:
		return (parts.torso.rb as RigidBody3D).linear_velocity
	return Vector3.ZERO


## True once the pile of parts has stopped sliding around.
func is_settled() -> bool:
	if not is_ragdoll:
		return true
	for p: Dictionary in parts.values():
		var rb: RigidBody3D = p.rb
		if rb and rb.linear_velocity.length() > 0.9:
			return false
	return true


## Which way to stand back up: the way the chest faces, or the way the back of
## the head points if the body is lying flat.
func ragdoll_yaw(fallback: float) -> float:
	if not is_ragdoll:
		return fallback
	var b: Basis = (parts.torso.rb as RigidBody3D).global_basis
	var f := -b.z
	f.y = 0.0
	if f.length() < 0.3:
		f = b.y
		f.y = 0.0
	if f.length() < 0.1:
		return fallback
	return atan2(-f.x, -f.z)


## Leaves ragdoll mode, blending each part from where it lies back into pose.
## The owner must move itself to the body first.
func recover() -> void:
	if not is_ragdoll:
		return
	_release(false)
	recovering = true
	_recover_t = 0.0


func clear_ragdoll() -> void:
	if is_ragdoll:
		_release(true)
	recovering = false


## Freezes the corpse, sinks it out of sight, then clears it. Used on death.
func sink_and_clear(duration := 1.2) -> void:
	if not is_ragdoll:
		return
	for p: Dictionary in parts.values():
		var rb: RigidBody3D = p.rb
		if rb:
			rb.freeze = true
			rb.freeze_mode = RigidBody3D.FREEZE_MODE_STATIC
			var tw := create_tween()
			tw.tween_property(rb, "global_position",
				rb.global_position + Vector3.DOWN * 0.8, duration)
	await get_tree().create_timer(duration, false, true).timeout
	clear_ragdoll()


func _process(delta: float) -> void:
	if not recovering:
		return
	_recover_t = minf(_recover_t + delta / RECOVER_TIME, 1.0)
	var t := smoothstep(0.0, 1.0, _recover_t)
	for key in _recover_from:
		var p: Dictionary = parts[key]
		var target: Transform3D = (p.pivot as Node3D).global_transform * (p.rest as Transform3D)
		(p.mesh as Node3D).global_transform = (_recover_from[key] as Transform3D).interpolate_with(target, t)
	if _recover_t >= 1.0:
		_finish_recover()


func _finish_recover() -> void:
	recovering = false
	for p: Dictionary in parts.values():
		(p.mesh as Node3D).transform = p.rest


func _release(snap: bool) -> void:
	for j in _joints:
		if is_instance_valid(j):
			j.queue_free()
	_joints.clear()
	_recover_from.clear()
	for key in parts:
		var p: Dictionary = parts[key]
		var rb: RigidBody3D = p.rb
		if rb == null:
			continue
		var mi: MeshInstance3D = p.mesh
		_recover_from[key] = mi.global_transform
		mi.reparent(p.pivot)
		rb.queue_free()
		p.rb = null
	reset_pose()
	if snap:
		_finish_recover()
	is_ragdoll = false


## A cone-twist joint is free to swing and twist around its local X axis, so
## point X down the limb and it hinges like an elbow without extra work.
func _joint(parent_key: String, child_key: String, at: Vector3, axis: Vector3,
		swing: float, twist: float) -> void:
	var j := ConeTwistJoint3D.new()
	get_tree().current_scene.add_child(j)
	j.global_transform = Transform3D(_basis_along(axis), at)
	j.set_param(ConeTwistJoint3D.PARAM_SWING_SPAN, deg_to_rad(swing))
	j.set_param(ConeTwistJoint3D.PARAM_TWIST_SPAN, deg_to_rad(twist))
	j.node_a = j.get_path_to(parts[parent_key].rb)
	j.node_b = j.get_path_to(parts[child_key].rb)
	_joints.append(j)


static func _basis_along(dir: Vector3) -> Basis:
	var x := dir.normalized()
	var up := Vector3.UP if absf(x.dot(Vector3.UP)) < 0.9 else Vector3.RIGHT
	var z := x.cross(up).normalized()
	var y := z.cross(x)
	return Basis(x, y, z)


# --- Construction helpers ----------------------------------------------------

func _pivot(parent: Node3D, pos: Vector3) -> Node3D:
	var n := Node3D.new()
	n.position = pos
	parent.add_child(n)
	_rest_pos[n] = pos
	return n


func _part(key: String, pivot: Node3D, offset: Vector3, mass: float, mesh: ArrayMesh) -> void:
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.position = offset
	pivot.add_child(mi)
	parts[key] = {pivot = pivot, mesh = mi, rest = mi.transform, mass = mass, rb = null}


func _vox(size: Vector3i, color_at: Callable) -> ArrayMesh:
	return VoxelMesh.build(size, VS, color_at)


## Sun-bleached shirt, a cross-strap, and grubby skin below the collar.
func _torso_col(x: int, y: int, z: int) -> Variant:
	if y == 0:
		return Palette.STRAP
	if (z == 0 or z == 3) and x == y:
		return Palette.STRAP
	if y == 5:
		return Palette.SKIN_SHADE
	if VoxelMesh.rand3(x, y, z, 11) < 0.06:
		return Palette.SKIN_SHADE
	return Palette.SHIRT


func _head_col(x: int, y: int, z: int) -> Variant:
	if z == 0:
		if y == 3 and (x == 1 or x == 3):
			return Palette.EYE
		if y == 1 and x >= 1 and x <= 3:
			return Palette.EYE.darkened(0.3)
	if y == 4:
		return Palette.SKIN.darkened(0.15)
	return Palette.SKIN


func _arm_col(_x: int, y: int, _z: int) -> Variant:
	if y == 0:
		return Palette.SKIN_SHADE
	return Palette.SKIN


func _leg_col(_x: int, y: int, _z: int) -> Variant:
	if y == 0:
		return Palette.SHOE
	return Palette.PANTS

