class_name Barrel
extends RigidBody3D
## A red barrel. Shoves, rolls, and punts the blockhead off its feet.

const RADIUS := 0.30
const HEIGHT := 0.80

var home := Vector3.ZERO
var _punt_cd := 0.0


func _init() -> void:
	collision_layer = Game.L_PROP
	collision_mask = Game.L_WORLD | Game.L_CHAR | Game.L_PROP | Game.L_RAGDOLL | Game.L_DEBRIS
	mass = 3.0
	contact_monitor = true
	max_contacts_reported = 6


func _ready() -> void:
	var f := func(x: int, y: int, z: int) -> Variant:
		var dx := x - 2.5
		var dz := z - 2.5
		if dx * dx + dz * dz > 6.6:
			return null
		if y == 0 or y == 7:
			return Palette.BARREL_BAND
		if y == 3 or y == 4:
			return Palette.RUST
		if VoxelMesh.rand3(x, y, z, 5) < 0.10:
			return Palette.BARREL_RED.darkened(0.35)
		return Palette.BARREL_RED
	var mi := MeshInstance3D.new()
	mi.mesh = VoxelMesh.build(Vector3i(6, 8, 6), 0.1, f)
	add_child(mi)

	var cs := CollisionShape3D.new()
	var cyl := CylinderShape3D.new()
	cyl.radius = RADIUS
	cyl.height = HEIGHT
	cs.shape = cyl
	add_child(cs)
	home = global_position


## A rolling barrel that catches the player at speed takes their legs out.
func _physics_process(delta: float) -> void:
	_punt_cd = maxf(_punt_cd - delta, 0.0)
	var speed := linear_velocity.length()
	if _punt_cd > 0.0 or speed < 2.2:
		return
	var p := Game.player as Player
	if p == null:
		return
	var to := p.global_position + Vector3.UP * 0.6 - global_position
	if to.length() > RADIUS + 0.85:
		return
	# Only a barrel that is actually rolling into the player counts.
	var dir := Vector3(linear_velocity.x, 0, linear_velocity.z).normalized()
	if dir.dot(Vector3(to.x, 0, to.z).normalized()) < 0.3:
		return
	_punt_cd = 0.7
	p.knock(global_position, clampf(speed * 1.1, 4.0, 11.0))
	apply_central_impulse(-dir * 1.2)


## Sends the barrel off in a direction — used when something shoves it.
func shove(dir: Vector3, force: float) -> void:
	apply_central_impulse(dir.normalized() * force)
	apply_torque_impulse(Vector3.UP * force * 0.4)

