class_name World
extends Node3D
## Builds the whole yard in code: grimy ground, brick walls, and roughly a
## hundred and twenty obstacles of five different kinds. Also owns the things
## the yard accumulates during play — blood on the floor, loose blocks, and the
## respawn timers that keep the props and pickups from running out.

const GRID := 48
const CELL := 0.4
const EXTENT := GRID * CELL * 0.5      # 9.6 — half the width of the yard
const WALL_T := 0.8
const WALL_H := 1.2
const MAX_DECALS := 80

const PROP_COUNTS := {
	"crate": 26,
	"barrel": 16,
	"stump": 18,
	"pillar": 8,
	"debris": 34,
}

var _decals: Node3D
var _decal_list: Array[Node3D] = []
var _rng := RandomNumberGenerator.new()


func _ready() -> void:
	Game.world = self
	_rng.seed = 20260925
	_decals = Node3D.new()
	_decals.name = "Decals"
	add_child(_decals)

	_build_ground()
	_build_walls()
	_build_detail()
	_scatter_props()
	_scatter_pickups()
	_lay_old_blood()


# --- Ground ------------------------------------------------------------------

func _build_ground() -> void:
	var voxels := {}
	for x in GRID:
		for z in GRID:
			voxels[Vector3i(x, 0, z)] = _ground_color(x, z)
	var mi := MeshInstance3D.new()
	mi.mesh = VoxelMesh.from_sparse(voxels, CELL, 0.16, Vector3(-EXTENT, -CELL * 0.5, -EXTENT))
	mi.name = "Ground"
	add_child(mi)

	# One box under the visible floor: cheap, and it never lets anything through.
	var body := StaticBody3D.new()
	body.collision_layer = Game.L_WORLD
	body.collision_mask = 0
	var cs := CollisionShape3D.new()
	var box := BoxShape3D.new()
	box.size = Vector3(EXTENT * 2.0, 1.0, EXTENT * 2.0)
	cs.shape = box
	cs.position.y = -0.5
	body.add_child(cs)
	add_child(body)

	# A skirt of darker earth so the floor does not look like a floating sheet.
	var skirt := {}
	var step := 8
	for x in range(-EXTENT, EXTENT, step * 0.1):
		for z in range(-EXTENT, EXTENT, step * 0.1):
			var ix := int(roundi(x / 0.1))
			var iz := int(roundi(z / 0.1))
			skirt[Vector3i(ix, 0, iz)] = Palette.DIRT_WET
	var sm := MeshInstance3D.new()
	sm.mesh = VoxelMesh.from_sparse(skirt, 0.1, 0.1, Vector3(-EXTENT, -1.0 - EXTENT, -EXTENT))
	sm.name = "Skirt"
	add_child(sm)


## Dirt by default, big soft patches of grass, and damp stone by the walls.
func _ground_color(x: int, z: int) -> Color:
	var fx := x / float(GRID)
	var fz := z / float(GRID)
	var blotch := VoxelMesh.noise2(x * 0.16, z * 0.16, 1)
	var detail := VoxelMesh.rand3(x, 0, z, 21)
	var edge := minf(minf(x, z), minf(GRID - 1 - x, GRID - 1 - z))

	if blotch > 0.56:
		if detail > 0.82:
			return Palette.GRASS_LIGHT
		return Palette.GRASS if detail > 0.3 else Palette.GRASS_DARK
	if blotch < 0.40 and detail > 0.72:
		return Palette.DIRT_WET
	if edge < 4:
		return Palette.STONE_DARK if detail > 0.6 else Palette.DIRT_DARK
	# A worn stone path curving through the middle of the yard.
	if absf(fx - fz) < 0.06 or absf(fx + fz - 1.0) < 0.05:
		return Palette.STONE if detail > 0.45 else Palette.STONE_DARK
	return Palette.DIRT if detail > 0.5 else Palette.DIRT_DARK


func _build_walls() -> void:
	var span := EXTENT * 2.0 + WALL_T
	for side in 4:
		var horizontal := side < 2
		var sign_z := -1.0 if side % 2 == 0 else 1.0
		var voxels := {}
		var len_cells := int(span / 0.2)
		var thick := int(WALL_T / 0.2)
		var high := int(WALL_H / 0.2)
		for i in len_cells:
			for t in thick:
				for h in high:
					var mossy := h == high - 1 and VoxelMesh.rand3(i, h, t, 31) < 0.35
					var c: Color = Palette.GRASS_DARK if mossy else (
						Palette.BRICK if (i / 6 + h / 2) % 2 == 0 else Palette.STONE)
					if VoxelMesh.rand3(i, h, t, 13) < 0.12:
						c = c.darkened(0.35)
					voxels[Vector3i(i, h, t)] = c
		var mi := MeshInstance3D.new()
		mi.mesh = VoxelMesh.from_sparse(voxels, 0.2, 0.14)
		mi.name = "Wall%d" % side
		add_child(mi)

		var body := StaticBody3D.new()
		body.collision_layer = Game.L_WORLD
		body.collision_mask = 0
		var cs := CollisionShape3D.new()
		var box := BoxShape3D.new()
		if horizontal:
			mi.position = Vector3(0, WALL_H * 0.5, sign_z * (EXTENT + WALL_T * 0.5))
			box.size = Vector3(span, WALL_H, WALL_T)
		else:
			mi.rotation_degrees = Vector3(0, 90, 0)
			mi.position = Vector3(sign_z * (EXTENT + WALL_T * 0.5), WALL_H * 0.5, 0)
			box.size = Vector3(span, WALL_H, WALL_T)
		cs.shape = box
		body.add_child(cs)
		body.position = mi.position
		add_child(body)
		mi.position.y = WALL_H * 0.5
		body.position.y = WALL_H * 0.5


# --- Scenery detail ----------------------------------------------------------

## Grass tufts and pebbles, all baked into two meshes so the yard is cheap to
## draw no matter how much litter is on the floor.
func _build_detail() -> void:
	var tufts := {}
	var pebbles := {}
	for i in 900:
		var p := _free_spot(0.7)
		if p == Vector3.INF:
			break
		var h := _rng.randi_range(1, 3)
		for k in h:
			var col: Color = Palette.GRASS_LIGHT if k == h - 1 else Palette.GRASS
			if VoxelMesh.rand3(i, k, 0, 5) < 0.2:
				col = Palette.GRASS_DARK
			_voxel_at(tufts, p + Vector3(randf_range(-0.05, 0.05), k * 0.09, randf_range(-0.05, 0.05)),
				0.09, col)
	for i in 260:
		var p := _free_spot(0.7)
		if p == Vector3.INF:
			break
		var w := _rng.randi_range(1, 2)
		_voxel_at(pebbles, p, 0.1, Palette.vary(Palette.STONE_LIGHT, i, 0.25))
		if w == 2:
			_voxel_at(pebbles, p + Vector3(0.1, 0, 0.05), 0.1, Palette.STONE)

	var tm := MeshInstance3D.new()
	tm.mesh = VoxelMesh.from_sparse(tufts, 0.09, 0.2, Vector3(-EXTENT, 0, -EXTENT))
	tm.name = "Tufts"
	add_child(tm)
	var pm := MeshInstance3D.new()
	pm.mesh = VoxelMesh.from_sparse(pebbles, 0.1, 0.2, Vector3(-EXTENT, 0, -EXTENT))
	pm.name = "Pebbles"
	add_child(pm)


func _voxel_at(dict: Dictionary, world: Vector3, cell: float, color: Color) -> void:
	var key := Vector3i(roundi((world.x + EXTENT) / cell), roundi(world.y / cell), roundi((world.z + EXTENT) / cell))
	dict[key] = color


# --- Props -------------------------------------------------------------------

func _scatter_props() -> void:
	var placed: Array[Vector3] = []
	for kind: String in PROP_COUNTS:
		var count: int = PROP_COUNTS[kind]
		for i in count:
			var p := _free_spot(0.75, placed)
			if p == Vector3.INF:
				continue
			placed.append(p)
			match kind:
				"crate":
					var c := Crate.new()
					c.position = p + Vector3(0, Crate.SIZE * 0.5, 0)
					add_child(c)
				"barrel":
					var b := Barrel.new()
					b.position = p + Vector3(0, Barrel.HEIGHT * 0.5 + 0.02, 0)
					add_child(b)
				"stump":
					var s := Stump.new()
					s.position = p
					add_child(s)
				"pillar":
					var q := Pillar.new()
					q.position = p
					add_child(q)
				"debris":
					spawn_debris(p + Vector3(0, 0.06, 0),
						Palette.vary(Palette.WOOD, i, 0.3), 0.0)


func _scatter_pickups() -> void:
	var placed: Array[Vector3] = []
	for i in 10:
		var p := _free_spot(1.2, placed)
		if p == Vector3.INF:
			continue
		placed.append(p)
		var m := MeatPickup.new()
		m.position = p
		add_child(m)


## A random spot inside the walls, kept away from the spawn point and from
## whatever is already there. Returns Vector3.INF if the yard is full.
func _free_spot(min_dist: float, taken: Array[Vector3] = []) -> Vector3:
	for attempt in 60:
		var p := Vector3(_rng.randf_range(-EXTENT + 1.2, EXTENT - 1.2), 0.01,
			_rng.randf_range(-EXTENT + 1.2, EXTENT - 1.2))
		if p.distance_to(Vector3(0, 0.01, 4.0)) < 2.0:
			continue                     # keep the spawn corner clear
		var ok := true
		for q in taken:
			if Vector2(p.x - q.x, p.z - q.z).length() < min_dist:
				ok = false
				break
		if ok:
			return p
	return Vector3.INF


# --- Things that accumulate during play ---------------------------------------

## A permanent dark patch on the floor. The yard keeps a record of every hit.
func add_blood(pos: Vector3, radius := 0.4) -> void:
	if _decals == null:
		return
	var q := QuadMesh.new()
	q.size = Vector2.ONE * radius * 2.0
	var m := StandardMaterial3D.new()
	m.albedo_color = Palette.BLOOD.darkened(_rng.randf_range(0.0, 0.3))
	m.albedo_color.a = 0.85
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.shading_mode = BaseMaterial3D.SHADING_MODE_PER_PIXEL
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	q.material = m
	var mi := MeshInstance3D.new()
	mi.mesh = q
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	mi.position = Vector3(pos.x, 0.012, pos.z)
	mi.rotation_degrees = Vector3(-90, 0, _rng.randf_range(0, 360))
	_decals.add_child(mi)
	_decal_list.append(mi)
	if _decal_list.size() > MAX_DECALS:
		var old: Node3D = _decal_list.pop_front()
		if is_instance_valid(old):
			old.queue_free()


## A few old stains, so the yard does not start spotless.
func _lay_old_blood() -> void:
	for i in 9:
		add_blood(Vector3(_rng.randf_range(-EXTENT + 2, EXTENT - 2), 0, _rng.randf_range(-EXTENT + 2, EXTENT - 2)),
			_rng.randf_range(0.35, 0.9))


func spawn_debris(pos: Vector3, color: Color, extra_velocity := Vector3.ZERO) -> void:
	var d := Debris.new(color, _rng.randf_range(0.12, 0.2))
	d.position = pos
	add_child(d)
	d.linear_velocity = extra_velocity
	d.angular_velocity = Vector3(_rng.randf_range(-8, 8), _rng.randf_range(-8, 8), _rng.randf_range(-8, 8))


func schedule_crate_respawn(pos: Vector3, delay: float) -> void:
	_run_later(delay, func() -> void:
		for c in get_tree().get_nodes_in_group("crates"):
			if (c as Node3D).global_position.distance_to(pos) < 0.8:
				return
		var crate := Crate.new()
		crate.position = pos + Vector3(0, Crate.SIZE * 0.5, 0)
		add_child(crate))


func schedule_pickup_respawn(pos: Vector3, delay: float) -> void:
	_run_later(delay, func() -> void:
		for m in get_tree().get_nodes_in_group("pickups"):
			if (m as Node3D).global_position.distance_to(pos) < 0.6:
				(m as MeatPickup).respawn()
				return
		var meat := MeatPickup.new()
		meat.position = pos
		add_child(meat))


func _run_later(delay: float, fn: Callable) -> void:
	await get_tree().create_timer(delay, false, true).timeout
	if is_instance_valid(self):
		fn.call()

