func _build_ground() -> void:
	var outer := EXTENT + APRON
	var step := 0.4
	var n := int(outer * 2.0 / step)
	var voxels := {}
	for ix in n:
		for iz in n:
			var wx := (ix + 0.5) * step - outer
			var wz := (iz + 0.5) * step - outer
			var inside := absf(wx) < EXTENT and absf(wz) < EXTENT
			var c := _ground_color(int((wx + EXTENT) / CELL), int((wz + EXTENT) / CELL)) if inside \
				else Palette.DIRT_WET if VoxelMesh.rand3(ix, 0, iz, 77) > 0.35 else Palette.STONE_DARK
			voxels[Vector3i(ix, 0, iz)] = c
	var mi := MeshInstance3D.new()
	mi.mesh = VoxelMesh.from_sparse(voxels, step, 0.14, Vector3(-outer, -step * 0.5, -outer))
	mi.name = "Ground"
	add_child(mi)

	# One box under the visible floor: cheap, and it never lets anything through.
	var body := StaticBody3D.new()
	body.collision_layer = Game.L_WORLD
	body.collision_mask = 0
	var cs := CollisionShape3D.new()
	var box := BoxShape3D.new()
	box.size = Vector3(outer * 2.0, 1.0, outer * 2.0)
	cs.shape = box
	cs.position.y = -0.5
	body.add_child(cs)
	add_child(body)

	# A skirt of darker earth so the floor does not look like a floating sheet.
	var skirt := BoxMesh.new()
	skirt.size = Vector3(outer * 2.0, 1.2, outer * 2.0)
	var sm := MeshInstance3D.new()
	sm.mesh = skirt
	sm.position = Vector3(0, -0.61, 0)
	sm.name = "Skirt"
	var sMat := StandardMaterial3D.new()
	sMat.albedo_color = Palette.DIRT_WET
	skirt.material = sMat
	add_child(sm)


## Dirt by default, big soft patches of grass, and damp stone by the walls.
## Three noise scales: the blotch decides which biome, the middle breaks up its
## edge, and a hash sprinkles the last bit of grit through it.
func _ground_color(x: int, z: int) -> Color:
	var blotch := VoxelMesh.noise2(x * 0.105, z * 0.105, 1)
	var mid := VoxelMesh.noise2(x * 0.36, z * 0.36, 2)
	var grit := VoxelMesh.rand3(x, 0, z, 21)
	var edge := minf(minf(x, z), minf(GRID - 1 - x, GRID - 1 - z))

	if blotch > 0.55:                                    # grass field
		if mid > 0.64:
			return Palette.GRASS_LIGHT
		return Palette.GRASS if mid > 0.34 else Palette.GRASS_DARK
	if blotch < 0.38 and mid > 0.60:                     # wet, trodden mud
		return Palette.DIRT_WET
	if edge < 4:
		return Palette.STONE_DARK if grit > 0.55 else Palette.DIRT_DARK
	# A worn stone path curving through the middle of the yard.
	var fx := x / float(GRID)
	var fz := z / float(GRID)
	if absf(fx - fz) < 0.055 or absf(fx + fz - 1.0) < 0.05:
		return Palette.STONE if grit > 0.45 else Palette.STONE_DARK
	return Palette.DIRT if mid > 0.4 else Palette.DIRT_DARK

