## Clears props out of a corridor so a scripted run is not at the mercy of
## whatever the scatter happened to drop in the way.
func _clear_lane(center: Vector2, half_width: float) -> void:
	for n in get_tree().get_nodes_in_group("crates"):
		var v := Vector2((n as Node3D).global_position.x, (n as Node3D).global_position.z)
		if absf(v.x - center.x) < half_width and v.y < center.y:
			n.queue_free()
	for child in get_children():
		if child is Barrel:
			var v := Vector2(child.global_position.x, child.global_position.z)
