## Clears props out of a corridor so a scripted run is not at the mercy of
## whatever the scatter happened to drop in the way. Everything movable *and*
## everything solid goes, so the lane is genuinely empty.
func _clear_lane(min_x: float, max_x: float, min_z: float, max_z: float) -> void:
	for n in get_tree().get_nodes_in_group("crates") + get_tree().get_nodes_in_group("scenery"):
		var v := Vector2((n as Node3D).global_position.x, (n as Node3D).global_position.z)
		if v.x > min_x and v.x < max_x and v.y > min_z and v.y < max_z:
			n.queue_free()
	for child in get_children():
		if child is RigidBody3D or child is Area3D:
			var v := Vector2(child.global_position.x, child.global_position.z)
			if v.x > min_x and v.x < max_x and v.y > min_z and v.y < max_z:
				child.queue_free()


## Walks a point down to a spot with nothing solid in the way, so a teleported
## blockhead never ends up wedged inside a stump.
func _clear_spot(from: Vector3, dir: Vector3, max_dist: float) -> Vector3:
	var space := get_world_3d().direct_space_state
	var p := from
	for step in 12:
		var q := PhysicsRayQueryParameters3D.create(
			p + Vector3.UP * 0.9, p + dir * (max_dist - step * 0.3) + Vector3.UP * 0.9,
			Game.L_WORLD | Game.L_PROP)
		q.exclude = [get_rid()]
		if space.intersect_ray(q).is_empty():
			return p
	return p

