func _step_ragdoll(delta: float) -> void:
	_ragdoll_time += delta
	var vel := rig.torso_velocity()
	var speed := vel.length()
	_detect_impact(vel, speed)
	_prev_torso_vel = vel

	if speed < 0.9:
		_settled_time += delta
	else:
		_settled_time = 0.0
	if _ragdoll_time > RAGDOLL_MIN_TIME and _settled_time > 0.35:
		if vigor <= 0.0:
			_die()
		else:
			_try_recover()


## A body part that loses most of its speed in one frame has just hit
## something. Dust, a shake, and a mark on the floor — so a flop reads as a
## landing and not as a body quietly stopping.
func _detect_impact(vel: Vector3, speed: float) -> void:
	if _ragdoll_time < 0.12 or speed > _prev_torso_vel.length():
		return
	var drop := _prev_torso_vel.length() - speed
	if drop < 5.0:
		return
	var at := rig.get_focus() + Vector3.UP * 0.4
	Game.burst(at, Palette.DIRT, 14, 3.2, 0.07, 0.55, 16.0)
	Game.camera.add_trauma(clampf(drop * 0.02, 0.05, 0.3))
	if drop > 8.0:
		Game.splat(at, 0.5)
		hurt(drop * 0.8)
		Game.burst(at, Palette.BLOOD, 8, 3.0, 0.05, 0.5, 18.0)


## Walking scuffs the loose blocks on the floor without having to collide
## with every pebble in the yard.
func _scuff_debris(speed: float, dir: Vector3) -> void:
	_scuff_cd -= get_physics_process_delta_time()
	if _scuff_cd > 0.0 or speed < 1.5:
		return
	_scuff_cd = 0.2
	for d in get_tree().get_nodes_in_group("debris"):
		var db := d as Debris
		if db == null or db.freeze:
			continue
		var to := db.global_position - global_position
		to.y = 0.0
		if to.length() > 0.9:
			continue
		db.apply_central_impulse(dir.normalized() * speed * 0.16 + Vector3.UP * 0.4)
		db.apply_torque_impulse(Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1)) * 0.4)

