// Minimal Chrome DevTools Protocol driver: opens the exported game, waits for
// it to settle, captures a screenshot, and reports anything the page logged.
// Usage: node web-check.mjs <url> <out.png> <waitMs>

const [, , url, out, waitMsArg] = process.argv;
const waitMs = Number(waitMsArg || 45000);

const list = await (await fetch("http://127.0.0.1:9222/json/new?about:blank", { method: "PUT" })).json();
const ws = new WebSocket(list.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const logs = [];

const send = (method, params = {}) =>
	new Promise((res) => {
		const msgId = ++id;
		pending.set(msgId, res);
		ws.send(JSON.stringify({ id: msgId, method, params }));
	});

ws.addEventListener("message", (ev) => {
	const msg = JSON.parse(ev.data);
	if (msg.id && pending.has(msg.id)) {
		pending.get(msg.id)(msg.result);
		pending.delete(msg.id);
		return;
	}
	if (msg.method === "Runtime.consoleAPICalled") {
		logs.push(`[${msg.params.type}] ` + msg.params.args.map((a) => a.value ?? a.description ?? a.type).join(" "));
	}
	if (msg.method === "Log.entryAdded") {
		logs.push(`[${msg.params.entry.level}] ${msg.params.entry.text}`);
	}
	if (msg.method === "Runtime.exceptionThrown") {
		logs.push(`[exception] ${msg.params.exceptionDetails.text} ${msg.params.exceptionDetails.exception?.description || ""}`);
	}
});

await new Promise((r) => ws.addEventListener("open", r));
await send("Page.enable");
await send("Runtime.enable");
await send("Log.enable");
await send("Page.navigate", { url });

// Poll the canvas until the engine has actually drawn something, then settle.
const deadline = Date.now() + waitMs;
let ready = false;
while (Date.now() < deadline) {
	await new Promise((r) => setTimeout(r, 1500));
	const probe = await send("Runtime.evaluate", {
		expression: `(() => {
			const c = document.querySelector('canvas');
			if (!c) return 'no-canvas';
			return c.width + 'x' + c.height;
		})()`,
		returnByValue: true,
	});
	const size = probe?.result?.value;
	if (size && size !== "0x0") {
		ready = true;
		console.log(`canvas live at ${size} after ${Math.round((waitMs - (deadline - Date.now())) / 1000)}s`);
		break;
	}
}
await new Promise((r) => setTimeout(r, 6000));

const shot = await send("Page.captureScreenshot", { format: "png" });
if (shot?.data) {
	const { writeFileSync } = await import("node:fs");
	writeFileSync(out, Buffer.from(shot.data, "base64"));
	console.log(`screenshot -> ${out}`);
} else {
	console.log("screenshot FAILED");
}
console.log("ready:", ready);
console.log("--- page log ---");
console.log(logs.length ? logs.join("\n") : "(nothing logged)");
await fetch(`http://127.0.0.1:9222/json/close/${list.id}`);
ws.close();
process.exit(0);

